export const getMinMax = (data) => {
    if (data.data.length === 0) {
        return { min: 0, max: 1 };
    }
    let min = Infinity;
    let max = -Infinity;
    for (let i = 0; i < data.data.length; i++) {
        const point = data.data[i];
        const value = point.y;
        if (value === null) {
            continue;
        }
        if (value < min) {
            min = value;
        }
        if (value > max) {
            max = value;
        }
    }
    if (min === Infinity && max === -Infinity) {
        return { min: 0, max: 1 };
    }
    return { min, max };
};
